/** How a cashback client is built. */
export interface CashbackApiOptions {
  /** The member's or operator's bearer token; every endpoint requires one. */
  readonly token?: string | null;
  /** Injected in tests; production uses the platform's `fetch`. */
  readonly fetch?: typeof fetch;
  /** `APP_ENV`. In `prod` an absent base URL is a refusal, never a fallback. */
  readonly appEnv?: string | undefined;
  /**
   * `PUBLIC_APP_VERSION`. A per-pull-request preview is the one deployment
   * stamped `pr-<n>`, and that stamp is what identifies it here. See
   * `createCashbackApi` and `isPreviewVersion`.
   */
  readonly appVersion?: string | undefined;
}

/**
 * Builds the client.
 *
 * With a base URL, requests go to the Go API. Without one the fixtures
 * answer — and that is a development convenience which must never reach a
 * member, because the fixtures state a balance. So:
 *
 *   - in `APP_ENV=prod` an absent base URL is REFUSED here, and the page
 *     fails rather than rendering. A deployment that cannot reach its API
 *     knows nothing about anybody's money, and saying nothing is the only
 *     truthful alternative to saying what is owed.
 *   - anywhere else the client answers but reports `source: 'fixture'`, so
 *     every surface can mark what it is showing.
 *
 * An `APP_ENV` that is neither value is refused before either branch, for
 * the reason the reader client gives: `prod` is a spelling, not a meaning,
 * and reading `production` as "not prod" would hand a deployed member a
 * wallet full of invented figures.
 */
/**
 * Whether this deployment answers cashback from built-in fixtures rather than
 * from an api.
 *
 * The same decision `createCashbackApi` makes, lifted out so that a caller
 * which is not building a client can ask it — the middleware's sign-in fence
 * needs to know, because a preview has no api and nobody signed in and its
 * whole job is to render the screens for review (issue #570).
 *
 * A configuration this refuses to read is NOT fixtures. `createCashbackApi`
 * throws for those, the page answers 503, and a visitor who is signed out is
 * better sent to sign in than shown a wallet that was never going to load.
 */
export function answersFromFixtures(
  baseUrl: string | undefined,
  options: Pick<CashbackApiOptions, 'appEnv' | 'appVersion'> = {},
): boolean {
  if (isPreviewVersion(options.appVersion)) {
    return true;
  }
  if (parseAppEnv(options.appEnv) === null) {
    return false;
  }
  return (
    (baseUrl === undefined || baseUrl === '') && parseAppEnv(options.appEnv) === APP_ENV_DEV
  );
}

export function createCashbackApi(
  baseUrl: string | undefined,
  options: CashbackApiOptions = {},
): CashbackApi {
  const appEnv = parseAppEnv(options.appEnv);
  // The per-pull-request preview is the one deployed environment that exists
  // to show a change to a reviewer, and it runs APP_ENV=prod deliberately, so
  // that what a reviewer sees is what a member would get. That fidelity is
  // also what makes the cashback surfaces invisible on it: previews do not
  // include docker-compose.cashback.yml, so CASHBACK_ENABLED is off, every
  // call is a 404, and the screens render an unavailable band. A preview that
  // cannot show the change defeats the reason previews exist.
  //
  // A preview is recognised by the one thing only a preview carries: its
  // version stamp. preview.yml writes `pr-<n>` into VERSION and the preview
  // compose passes it as PUBLIC_APP_VERSION; every other environment carries
  // the release tag the pipeline deployed, or nothing. Reading that stamp
  // reaches a preview from the pull request itself - an environment variable
  // in the compose file would not, because the host copies compose files at
  // provision time and a pull request cannot change them.
  //
  // What keeps this narrow: CI stamps the version, not a visitor, so no query
  // parameter, cookie, header or link can trigger it; a fixture client moves
  // no money and refuses every operator decision with a 503 naming itself;
  // its click-out redirects back to the deployment rather than to a shop; and
  // every surface renders the fixture band above its content, in the reading
  // language, saying the figures are invented. It is scoped to cashback - the
=== test comment ===
